@router.get("/options", dependencies=[Depends(require_permission("reports.view"))])
def options(db: Session = Depends(database.get_db)):
    names = {}
    for (props,) in db.query(models.Visitor.properties).all():
        p = get_project(props or {}) or NO_PROJECT
        names[p] = names.get(p, 0) + 1
    projects = [
        {"project": p, "visitors": names[p]} for p in sorted(names, key=_project_order)
    ]
    return {
        "types": [{"key": k, "label": v} for k, v in TYPES.items()],
        "expiry_fields": [{"key": k, "label": v[0]} for k, v in EXPIRY_FIELDS.items()],
        "projects": projects,
        "warn_days": get_int_setting(db, KEY_EXPIRY_DAYS, DEFAULT_EXPIRY_DAYS),
    }


@router.get("", dependencies=[Depends(require_permission("reports.view"))])
def preview(
    type: str = Query("activity"),
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    project: Optional[str] = None,
    action: Optional[str] = None,
    field: str = "all",
    status: Optional[str] = None,
    warn_days: Optional[int] = Query(None, ge=0, le=3650),
    db: Session = Depends(database.get_db),
):
    rep = build_report(db, type, date_from, date_to, project, action, field, status, warn_days)
    total = len(rep["rows"])
    return {
        **rep,
        "rows": rep["rows"][:PREVIEW_ROWS],
        "total": total,
        "truncated": total > PREVIEW_ROWS,
    }


@router.get("/export", dependencies=[Depends(require_permission("reports.export"))])
def export(
    type: str = Query("activity"),
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    project: Optional[str] = None,
    action: Optional[str] = None,
    field: str = "all",
    status: Optional[str] = None,
    warn_days: Optional[int] = Query(None, ge=0, le=3650),
    db: Session = Depends(database.get_db),
):
    rep = build_report(db, type, date_from, date_to, project, action, field, status, warn_days)
    content = build_xlsx(rep)
    filename = "kav1_{}_{}.xlsx".format(type, datetime.now().strftime("%Y%m%d_%H%M"))
    return StreamingResponse(
        iter([content]),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers=_attachment(filename),
    )

